({
  params: [
    /* ------------------------------------------------------------- the hill */
    { key: "siteX",     label: "Site width",          def: 4200, min: 1500, max: 12000, step: 100 },
    { key: "siteY",     label: "Site depth",          def: 3000, min: 1000, max: 9000,  step: 100 },
    { key: "peak",      label: "Hill height",         def: 1150, min: 100,  max: 4000,  step: 25 },
    { key: "crest",     label: "Crest across",        def: 0.55, min: 0,    max: 1,     step: 0.01, unit: "" },
    { key: "shoulder",  label: "Crest width",         def: 0.46, min: 0.15, max: 1.2,   step: 0.01, unit: "" },
    { key: "fold",      label: "Side folds",          def: 0.16, min: 0,    max: 0.6,   step: 0.01, unit: "" },
    { key: "sections",  label: "Terrain sections",    def: 16,   min: 4,    max: 36,    step: 1, unit: "" },
    { key: "samples",   label: "Points per section",  def: 26,   min: 6,    max: 60,    step: 2, unit: "" },
    { key: "ground",    label: "Ground",              options: ["On", "Off"], def: 0 },

    /* ------------------------------------------------------------- the plan */
    { key: "rows",      label: "Terrace rows",        def: 2,    min: 1,    max: 3,     step: 1, unit: "" },
    { key: "bay",       label: "Bay spacing",         def: 1150, min: 300,  max: 4000,  step: 25 },
    { key: "setback",   label: "Front set-back",      def: 620,  min: 0,    max: 3000,  step: 20 },
    { key: "rowStep",   label: "Row set-back",        def: 900,  min: 150,  max: 3000,  step: 20 },

    /* ------------------------------------------------------------ the villa */
    { key: "villaX",    label: "Villa depth",         def: 330,  min: 120,  max: 1200,  step: 10 },
    { key: "villaY",    label: "Villa width",         def: 460,  min: 120,  max: 1600,  step: 10 },
    { key: "storey",    label: "Floor to floor",      def: 165,  min: 80,   max: 400,   step: 5 },
    { key: "storeys",   label: "Storeys",             def: 2,    min: 1,    max: 4,     step: 1, unit: "" },
    { key: "eaves",     label: "Slab overhang",       def: 42,   min: 0,    max: 200,   step: 2 },
    { key: "roofRise",  label: "Roof rise",           def: 95,   min: 0,    max: 400,   step: 5 },
    { key: "mullion",   label: "Mullion spacing",     def: 62,   min: 20,   max: 400,   step: 2 },
    { key: "deck",      label: "Deck margin",         def: 250,  min: 40,   max: 1200,  step: 10 },
    { key: "pool",      label: "Pool length",         def: 0.62, min: 0,    max: 0.92,  step: 0.01, unit: "" },
    { key: "rail",      label: "Balustrade height",   def: 56,   min: 20,   max: 160,   step: 1 },
    { key: "postBay",   label: "Post spacing",        def: 78,   min: 25,   max: 400,   step: 2 },

    /* --------------------------------------------------- each villa, by hand
       Turn is added to the rule, so zero leaves the villa facing straight down
       the slope. Push slides it along that same line in plan, and it climbs or
       drops because the hill is asked again where it lands.                  */
    { key: "turn1", label: "Villa 1 · turn", def:   0, min: -180, max: 180, step: 1, unit: "°" },
    { key: "push1", label: "Villa 1 · push", def:   0, min: -1500, max: 1500, step: 10 },
    { key: "turn2", label: "Villa 2 · turn", def:  14, min: -180, max: 180, step: 1, unit: "°" },
    { key: "push2", label: "Villa 2 · push", def: 120, min: -1500, max: 1500, step: 10 },
    { key: "turn3", label: "Villa 3 · turn", def: -12, min: -180, max: 180, step: 1, unit: "°" },
    { key: "push3", label: "Villa 3 · push", def:   0, min: -1500, max: 1500, step: 10 },
    { key: "turn4", label: "Villa 4 · turn", def:  22, min: -180, max: 180, step: 1, unit: "°" },
    { key: "push4", label: "Villa 4 · push", def: -90, min: -1500, max: 1500, step: 10 },
    { key: "turn5", label: "Villa 5 · turn", def:  -8, min: -180, max: 180, step: 1, unit: "°" },
    { key: "push5", label: "Villa 5 · push", def:   0, min: -1500, max: 1500, step: 10 },
    { key: "turn6", label: "Villa 6 · turn", def:  18, min: -180, max: 180, step: 1, unit: "°" },
    { key: "push6", label: "Villa 6 · push", def: 150, min: -1500, max: 1500, step: 10 },
  ],

  build(p, k) {
    /* ======================================================================
       A hillside town, in four moves.

         1  the hill      one function, z = H(x, y). Nothing else on this site
                          holds a height; everything asks it.
         2  the ground    that function lofted into a solid, section by section
         3  the plan      six centre points drawn flat on the site, in 2D, with
                          no idea that there is a hill at all
         4  the town      each centre dropped onto the hill, turned to face
                          downhill, and a villa put there

       Which is how a hillside is actually laid out: you draw the plan on the
       survey, and the survey tells you what happens to it.
       ====================================================================== */

    const VILLAS = 6;
    const smooth = t => t * t * (3 - 2 * t);
    const clamp = (t, lo, hi) => Math.max(lo, Math.min(hi, t));

    /* ---------------------------------------------------------- 1 · the hill

       x runs across the slope, y up it. The shore is at y = 0 and the ridge at
       the back; a gaussian across x gives the crest its shoulder, and a cosine
       folds the flanks into spurs and gullies.                              */

    const hill = (x, y) => {
      const u = clamp(x / p.siteX, 0, 1), v = clamp(y / p.siteY, 0, 1);
      const rise = smooth(v);
      const along = Math.exp(-Math.pow((u - p.crest) / p.shoulder, 2));
      const folds = Math.cos(u * Math.PI * 4) * p.fold * v;
      return p.peak * rise * (0.30 + 0.70 * along + folds);
    };

    //! Which way the water runs, in degrees. A villa faces this by default,
    //! and a per-villa turn is added to it.
    const aspect = (x, y) => {
      const e = Math.max(1, p.siteX * 0.004);
      const dx = hill(x + e, y) - hill(x - e, y);
      const dy = hill(x, y + e) - hill(x, y - e);
      if (Math.abs(dx) < 1e-9 && Math.abs(dy) < 1e-9) return -90;
      return Math.atan2(-dy, -dx) * 180 / Math.PI;
    };

    /* -------------------------------------------------------- 2 · the ground

       One closed section per station up the slope: the ground line across the
       site, then straight down and back, so the profile encloses something.
       Lofted through, they are a solid with a landscape on top.             */

    const parts = [];
    const base = p.peak * 0.12 + 60;
    const samples = Math.max(6, Math.round(p.samples));
    const sections = Math.max(3, Math.round(p.sections));

    if (p.ground === 0) {
      const profiles = [];
      for (let j = 0; j <= sections; j++) {
        const y = p.siteY * j / sections;
        const line = [];
        for (let i = 0; i <= samples; i++) {
          const x = p.siteX * i / samples;
          line.push([x, y, hill(x, y)]);
        }
        line.push([p.siteX, y, -base], [0, y, -base]);
        profiles.push(k.polyline(line, { closed: true }));
      }
      parts.push(k.loft(profiles, { solid: true, ruled: true }));
    }

    /* ---------------------------------------------------------- 3 · the plan

       Flat. Two dimensions. The villas sit on terrace rows set back up the
       slope, evenly spaced along each row, centred on the site. This is the
       only place the layout is decided, and it never mentions z.            */

    const rows = clamp(Math.round(p.rows), 1, 3);
    const perRow = Math.ceil(VILLAS / rows);
    const plan = i => {
      const row = Math.floor(i / perRow), col = i % perRow;
      const x = p.siteX / 2 + (col - (perRow - 1) / 2) * p.bay;
      const y = p.setback + row * p.rowStep;
      return [x, y];
    };

    /* --------------------------------------------------------- 4 · the villa

       Built once, at the origin, facing +X. Six copies are placed by moving
       and turning that one shape - the same trick the Array feature uses, and
       the reason six villas cost about what one does.                       */

    const deckX = p.villaX + 2 * p.deck;
    const deckY = p.villaY + 2 * p.deck;
    const box = (dx, dy, dz, at) =>
      k.box(dx, dy, dz, { at, axis: [0, 0, 1], xdir: [1, 0, 0] });

    const villa = (() => {
      const bits = [];

      // The terrace, on a plinth that reaches down into the hill whatever the
      // slope does under it. The pool is cut out of the downhill margin.
      const plinth = Math.max(260, p.peak * 0.6);
      let terrace = box(deckX, deckY, plinth, [-deckX / 2, -deckY / 2, -plinth]);
      if (p.pool > 0.03) {
        const poolY = deckY * p.pool, poolX = p.deck * 0.6, poolD = Math.max(20, p.deck * 0.3);
        terrace = k.cut(terrace, box(poolX, poolY, poolD * 3,
          [p.villaX / 2 + (p.deck - poolX) / 2, -poolY / 2, -poolD]));
      }
      bits.push(terrace);

      // Slabs and glass. The slab oversails on every side, the glass is set
      // back behind its edge, and the mullions run up the view face.
      const levels = clamp(Math.round(p.storeys), 1, 4);
      const slab = Math.max(6, p.storey * 0.085);
      const overX = p.villaX + 2 * p.eaves, overY = p.villaY + 2 * p.eaves;
      const inset = slab * 0.6;
      const glassX = p.villaX - 2 * inset, glassY = p.villaY - 2 * inset;
      const bays = Math.max(1, Math.round(glassY / p.mullion));
      const post = Math.max(3, p.rail * 0.085);

      for (let i = 0; i <= levels; i++)
        bits.push(box(overX, overY, slab, [-overX / 2, -overY / 2, i * p.storey]));

      for (let i = 0; i < levels; i++) {
        const z = i * p.storey + slab;
        const h = p.storey - slab;
        bits.push(box(glassX, glassY, h, [-glassX / 2, -glassY / 2, z]));
        // Mullions up the view face and both flanks - the three sides that are
        // glass. The back is where the hill is.
        const rib = post * 1.3;
        for (let m = 0; m <= bays; m++) {
          const y = -glassY / 2 + glassY * m / bays;
          bits.push(box(rib, rib, h, [glassX / 2 - post, y - rib / 2, z]));
        }
        const deep = Math.max(1, Math.round(glassX / p.mullion));
        for (let m = 0; m <= deep; m++) {
          const x = -glassX / 2 + glassX * m / deep;
          bits.push(box(rib, rib, h, [x - rib / 2, glassY / 2 - post, z]));
          bits.push(box(rib, rib, h, [x - rib / 2, -glassY / 2 + post - rib, z]));
        }
      }

      // The roof: the eaves rectangle lofted up to a short ridge, so it hips
      // in on all four sides. Rise to nothing and it is a flat roof instead.
      const top = levels * p.storey + slab;
      if (p.roofRise > 2) {
        bits.push(k.loft([
          k.rectangle(overX, overY, { at: [0, 0, top], axis: [0, 0, 1], xdir: [1, 0, 0] }),
          k.rectangle(overX * 0.16, overY * 0.66,
            { at: [0, 0, top + p.roofRise], axis: [0, 0, 1], xdir: [1, 0, 0] }),
        ], { solid: true, ruled: true }));
      } else {
        bits.push(box(overX, overY, slab, [-overX / 2, -overY / 2, top]));
      }

      // Balustrade round three sides of the deck: the view, and both flanks.
      // The uphill side is where you arrive, so it is left open.
      const runs = [
        [[deckX / 2 - post, -deckY / 2 + post], [deckX / 2 - post, deckY / 2 - post]],
        [[-deckX / 2 + post, deckY / 2 - post], [deckX / 2 - post, deckY / 2 - post]],
        [[-deckX / 2 + post, -deckY / 2 + post], [deckX / 2 - post, -deckY / 2 + post]],
      ];
      for (const [a, b] of runs) {
        const span = Math.hypot(b[0] - a[0], b[1] - a[1]);
        const n = Math.max(1, Math.round(span / p.postBay));
        for (let i = 0; i <= n; i++) {
          const t = i / n;
          const x = a[0] + (b[0] - a[0]) * t, y = a[1] + (b[1] - a[1]) * t;
          bits.push(box(post, post, p.rail, [x - post / 2, y - post / 2, 0]));
        }
        bits.push(k.beam([a[0], a[1], p.rail], [b[0], b[1], p.rail], post * 2.2, post * 1.1));
      }

      return k.compound(bits);
    })();

    /* ----------------------------------------------------------- the town

       Each centre point, projected. The hill is asked for its height there and
       for which way it falls; the villa is turned to face that, plus whatever
       this one has been turned by hand; and push slides it along the same line
       in plan, so a villa pushed downhill really does come down the hill.   */

    for (let i = 0; i < VILLAS; i++) {
      const [x0, y0] = plan(i);
      const facing = aspect(x0, y0);
      const rad = facing * Math.PI / 180;
      const push = p["push" + (i + 1)] || 0;
      const x = clamp(x0 + Math.cos(rad) * push, deckX * 0.5, p.siteX - deckX * 0.5);
      const y = clamp(y0 + Math.sin(rad) * push, deckY * 0.5, p.siteY - deckY * 0.5);
      const turned = k.rotate(villa, facing + (p["turn" + (i + 1)] || 0),
                              { at: [0, 0, 0], axis: [0, 0, 1] });
      parts.push(k.move(turned, [x, y, hill(x, y)]));
    }

    return k.compound(parts);
  },
})
